/**
 * Command registry tests (issue UI-012 acceptance: "shortcut conflict test
 * exists", "all commands have Japanese labels").
 *
 * Pure logic — no DOM needed.
 */

import { describe, expect, it, vi } from "vitest";
import { ja } from "../strings/ja";
import { CommandRegistry, createCommandRegistry } from "./registry";
import type {
  Command,
  CommandContext,
  CommandSnapshot,
} from "./types";

const SNAPSHOT_EMPTY: CommandSnapshot = {
  hasAudio: false,
  hasScore: false,
  isTranscribing: false,
  isPlaying: false,
  loopEnabled: false,
  pitch: "concert",
  canUndo: false,
  canRedo: false,
  hasSelection: false,
  hasRestSelection: false,
  hasWaveformSelection: false,
  reviewOpen: false,
  reviewIssueEditable: false,
  reviewCount: 0,
      isRecording: false,
      isRecordingPaused: false,
      auditionEnabled: false,
  view: "workspace",
};

const SNAPSHOT_SCORE: CommandSnapshot = {
  ...SNAPSHOT_EMPTY,
  hasAudio: true,
  hasScore: true,
  canUndo: true,
  canRedo: true,
  hasSelection: true,
  reviewCount: 3,
      isRecording: false,
      isRecordingPaused: false,
      auditionEnabled: false,
};

function mockContext(): CommandContext & { calls: string[] } {
  const calls: string[] = [];
  const spy = (name: string) => vi.fn(() => calls.push(name));
  return {
    calls,
    openAudio: spy("openAudio"),
    transcribe: spy("transcribe"),
    togglePlayPause: spy("togglePlayPause"),
    stop: spy("stop"),
    jumpBack: spy("jumpBack"),
    jumpForward: spy("jumpForward"),
    seekToStart: spy("seekToStart"),
    seekToEnd: spy("seekToEnd"),
    toggleLoop: spy("toggleLoop"),
    setPitchView: spy("setPitchView"),
    openReview: spy("openReview"),
    reviewNext: spy("reviewNext"),
    reviewPrevious: spy("reviewPrevious"),
    undo: spy("undo"),
    redo: spy("redo"),
    openExport: spy("openExport"),
    openInMuseScore: spy("openInMuseScore"),
    saveProject: spy("saveProject"),
    saveProjectAs: spy("saveProjectAs"),
    noteDurationScale: spy("noteDurationScale"),
    shiftSelectedOnset: spy("shiftSelectedOnset"),
    toggleSelectedTie: spy("toggleSelectedTie"),
    zoomScoreIn: spy("zoomScoreIn"),
    zoomScoreOut: spy("zoomScoreOut"),
    zoomScoreFit: spy("zoomScoreFit"),
    clearSelection: spy("clearSelection"),
    openSettings: spy("openSettings"),
    openDiagnostics: spy("openDiagnostics"),
    focusNextRegion: spy("focusNextRegion"),
    focusPreviousRegion: spy("focusPreviousRegion"),
    announce: spy("announce"),
  };
}

describe("command definitions", () => {
  const registry = createCommandRegistry();

  it("covers every command required by UI-012 / GUI_UX_SPEC", () => {
    const ids = registry.list().map((c) => c.id);
    for (const required of [
      "file.openAudio",
      "score.transcribe",
      "transport.playPause",
      "transport.stop",
      "transport.jumpBack",
      "transport.jumpForward",
      "transport.toggleLoop",
      "view.concertPitch",
      "view.hornF",
      "review.open",
      "review.next",
      "review.previous",
      "review.playSource",
      "review.accept",
      "review.dismiss",
      "review.pitchUp",
      "review.pitchDown",
      "review.deleteOrRestore",
      "review.exit",
      "edit.undo",
      "edit.redo",
      "export.open",
      "export.openInMuseScore",
      "score.zoomIn",
      "score.zoomOut",
      "score.zoomFit",
      "score.noteLonger",
      "score.noteShorter",
      "score.noteShiftLeft",
      "score.noteShiftRight",
      "score.toggleTie",
      "nav.nextRegion",
      "nav.previousRegion",
      "app.settings",
      "app.diagnostics",
    ]) {
      expect(ids).toContain(required);
    }
  });

  it("ships with zero shortcut conflicts", () => {
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("every command has a non-empty Japanese title", () => {
    const known = new Set<string>(Object.values(ja.commands));
    for (const command of registry.list()) {
      expect(command.title.length).toBeGreaterThan(0);
      // Titles come from the shared copy module, not ad-hoc strings.
      expect(known.has(command.title)).toBe(true);
    }
  });

  it("initial bindings match the spec table (§9, §15, §22)", () => {
    const shortcutOf = (id: string) =>
      registry.get(id)?.shortcuts ?? [];
    expect(shortcutOf("file.openAudio")).toContain("Ctrl+O");
    expect(shortcutOf("transport.playPause")).toEqual(
      expect.arrayContaining(["Space", "K"]),
    );
    expect(shortcutOf("transport.stop")).toContain("Shift+Space");
    expect(shortcutOf("transport.jumpBack")).toContain("J");
    expect(shortcutOf("transport.jumpForward")).toContain("L");
    expect(shortcutOf("transport.toggleLoop")).toContain("Ctrl+L");
    expect(shortcutOf("view.concertPitch")).toContain("Ctrl+1");
    expect(shortcutOf("view.hornF")).toContain("Ctrl+2");
    expect(shortcutOf("edit.undo")).toContain("Ctrl+Z");
    expect(shortcutOf("edit.redo")).toContain("Ctrl+Shift+Z");
    // UI-050 review keys (P4-validated set).
    expect(shortcutOf("review.next")).toContain("ArrowRight");
    expect(shortcutOf("review.previous")).toContain("ArrowLeft");
    expect(shortcutOf("review.playSource")).toContain("R");
    expect(shortcutOf("review.accept")).toContain("O");
    expect(shortcutOf("review.dismiss")).toContain("Shift+O");
    expect(shortcutOf("review.pitchUp")).toContain("Alt+ArrowUp");
    expect(shortcutOf("review.pitchDown")).toContain("Alt+ArrowDown");
    expect(shortcutOf("review.deleteOrRestore")).toContain("Delete");
    expect(shortcutOf("export.open")).toContain("Ctrl+E");
    // #221: project save pair — Ctrl+S writes back, Ctrl+Shift+S re-picks.
    expect(shortcutOf("project.save")).toContain("Ctrl+S");
    expect(shortcutOf("project.saveAs")).toContain("Ctrl+Shift+S");
    expect(shortcutOf("score.zoomIn")).toEqual(
      expect.arrayContaining(["Ctrl+=", "Ctrl++"]),
    );
    expect(shortcutOf("score.zoomOut")).toContain("Ctrl+-");
    expect(shortcutOf("score.zoomFit")).toContain("Ctrl+0");
    expect(shortcutOf("nav.nextRegion")).toContain("F6");
    expect(shortcutOf("nav.previousRegion")).toContain("Shift+F6");
  });

  it("#221: project save pair gates on a score and invokes the ctx", () => {
    const ctx = mockContext();
    // No score → both stay unavailable; a running job also locks them.
    for (const id of ["project.save", "project.saveAs"]) {
      expect(registry.invoke(id, ctx, SNAPSHOT_EMPTY)).toBe(false);
      expect(
        registry.invoke(id, ctx, {
          ...SNAPSHOT_SCORE,
          isTranscribing: true,
        }),
      ).toBe(false);
      expect(registry.invoke(id, ctx, SNAPSHOT_SCORE)).toBe(true);
    }
    expect(ctx.calls).toEqual(["saveProject", "saveProjectAs"]);
  });

  it("#115: rhythm edits gate on a note selection and invoke the ctx", () => {
    const ctx = mockContext();
    // SNAPSHOT_SCORE has a selection; EMPTY does not.
    for (const id of [
      "score.noteLonger",
      "score.noteShorter",
      "score.noteShiftLeft",
      "score.noteShiftRight",
      "score.toggleTie",
    ]) {
      expect(registry.invoke(id, ctx, SNAPSHOT_EMPTY)).toBe(false);
      expect(registry.invoke(id, ctx, SNAPSHOT_SCORE)).toBe(true);
    }
    expect(ctx.calls).toEqual([
      "noteDurationScale",
      "noteDurationScale",
      "shiftSelectedOnset",
      "shiftSelectedOnset",
      "toggleSelectedTie",
    ]);
    // Review owns the arrows/keys — rhythm edits stay disabled inside it.
    const reviewing: CommandSnapshot = { ...SNAPSHOT_SCORE, reviewOpen: true };
    expect(registry.invoke("score.toggleTie", ctx, reviewing)).toBe(false);
  });
});

describe("conflict detection", () => {
  const cmd = (over: Partial<Command> & { id: string }): Command => ({
    title: "テスト",
    section: "app",
    run: () => undefined,
    ...over,
  });

  it("detects two commands bound to the same chord", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+P"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+P"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([
      { shortcut: "Ctrl+P", commandIds: ["a.one", "b.two"] },
    ]);
  });

  it("normalizes bindings before comparing (Ctrl+shift+p == Ctrl+Shift+P)", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+Shift+P"] }),
      cmd({ id: "b.two", shortcuts: ["ctrl+shift+p"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("detects multi-chord sequence collisions", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K Ctrl+C"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    expect(registry.detectConflicts()).toHaveLength(1);
  });

  it("does not flag two bindings owned by the same command", () => {
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Space", "K"] }),
      cmd({ id: "b.two", shortcuts: ["L"] }),
    ]);
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("does not flag a chord vs. a longer sequence sharing its prefix", () => {
    // "Ctrl+K" alone and "Ctrl+K Ctrl+C" coexist: the single chord fires
    // immediately, so this is intentionally strict — they DO conflict at
    // the dispatcher level… except the first chord completes its binding
    // before the sequence can continue. Flagging it keeps authors honest:
    // sequences must not share their first chord with a single binding.
    const registry = new CommandRegistry([
      cmd({ id: "a.one", shortcuts: ["Ctrl+K"] }),
      cmd({ id: "b.two", shortcuts: ["Ctrl+K Ctrl+C"] }),
    ]);
    // Distinct normalized keys — no conflict between the *sequences*, the
    // dispatcher resolves "Ctrl+K" as a full match before any second chord.
    expect(registry.detectConflicts()).toEqual([]);
  });

  it("createCommandRegistry throws when definitions contain a conflict", () => {
    expect(() =>
      createCommandRegistry([
        cmd({ id: "a.one", shortcuts: ["Ctrl+X"] }),
        cmd({ id: "b.two", shortcuts: ["Ctrl+X"] }),
      ]),
    ).toThrow(/conflict/i);
  });

  it("register() rejects a duplicate command id", () => {
    const registry = new CommandRegistry([cmd({ id: "a.one" })]);
    expect(() => registry.register(cmd({ id: "a.one" }))).toThrow(
      /duplicate/i,
    );
  });
});

describe("invoke", () => {
  const registry = createCommandRegistry();

  it("runs an enabled command", () => {
    const ctx = mockContext();
    expect(registry.invoke("file.openAudio", ctx, SNAPSHOT_EMPTY)).toBe(true);
    expect(ctx.calls).toEqual(["openAudio"]);
  });

  it("refuses a disabled command — non-executable from any surface", () => {
    const ctx = mockContext();
    // 採譜 needs audio; EMPTY state has none.
    expect(registry.invoke("score.transcribe", ctx, SNAPSHOT_EMPTY)).toBe(
      false,
    );
    expect(ctx.transcribe).not.toHaveBeenCalled();
  });

  it("returns false for unknown ids", () => {
    const ctx = mockContext();
    expect(registry.invoke("no.such", ctx, SNAPSHOT_EMPTY)).toBe(false);
  });

  it("enables transport/edit/export once a score exists", () => {
    const ctx = mockContext();
    for (const [id, spy] of [
      ["transport.toggleLoop", "toggleLoop"],
      ["edit.undo", "undo"],
      ["export.open", "openExport"],
      ["export.openInMuseScore", "openInMuseScore"],
      ["review.next", null], // needs reviewOpen — stays disabled
    ] as const) {
      const ran = registry.invoke(id, ctx, SNAPSHOT_SCORE);
      if (spy) {
        expect(ran).toBe(true);
        expect(ctx.calls).toContain(spy);
      } else {
        expect(ran).toBe(false);
      }
    }
  });
});

describe("visibility", () => {
  const registry = createCommandRegistry();

  it("review commands stay off surfaces until a review exists", () => {
    const visibleEmpty = registry
      .listVisible(SNAPSHOT_EMPTY)
      .map((c) => c.id);
    expect(visibleEmpty).not.toContain("review.open");
    expect(visibleEmpty).not.toContain("review.next");

    const reviewing: CommandSnapshot = {
      ...SNAPSHOT_SCORE,
      reviewOpen: true,
    };
    const visibleReview = registry
      .listVisible(reviewing)
      .map((c) => c.id);
    expect(visibleReview).toContain("review.open");
    expect(visibleReview).toContain("review.next");
    expect(visibleReview).toContain("review.previous");
  });
});

/**
 * Command model types (docs/GUI_UX_SPEC.md §23).
 *
 * A Command is a *stateless* description: predicates receive a
 * CommandSnapshot so the same definitions can be evaluated for menus,
 * keyboard dispatch, palette listing and tests without re-registering.
 */

/** Pitch display modes (GUI_UX_SPEC §7). Kept literal here so the command
 *  layer does not depend on a component file. */
export type PitchViewSetting = "concert" | "hornF";

/** Top-level screens that gate command availability. */
export type AppView = "workspace" | "settings";

/** Grouping for menus / command palette / docs. */
export type CommandSection =
  | "file"
  | "score"
  | "transport"
  | "view"
  | "review"
  | "edit"
  | "export"
  | "nav"
  | "app";

/**
 * Immutable read of the app state that command predicates evaluate.
 * The app builds one per render; the registry never stores it.
 */
export interface CommandSnapshot {
  /** A source audio file is loaded (GUI_UX_SPEC §4, AUDIO_READY+). */
  readonly hasAudio: boolean;
  /** A canonical score exists (SCORE_READY+). */
  readonly hasScore: boolean;
  /** Transcription is running — score-writing commands disable (§5). */
  readonly isTranscribing: boolean;
  /** Audio is currently playing (drives the play/pause affordance). */
  readonly isPlaying: boolean;
  /** Loop range playback is armed. */
  readonly loopEnabled: boolean;
  /** Current pitch display mode. */
  readonly pitch: PitchViewSetting;
  /** Undo/redo stacks (§14 — all edits are commands). */
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** A note/region is selected (gates Esc = clear selection). */
  readonly hasSelection: boolean;
  /** #163: the score selection is a rest glyph — gates restToNote. */
  readonly hasRestSelection: boolean;
  /** #113: a waveform range selection exists (AUDIO_READY). Esc clears
   *  this before any score selection (spec 8: Esc -> 選択解除). */
  readonly hasWaveformSelection: boolean;
  /** 要確認 workspace state. */
  readonly reviewOpen: boolean;
  /** The issue under the review cursor targets notes - gates the
   *  review pitch/delete shortcuts so they go inert on whole-piece
   *  issues instead of silently doing nothing. */
  readonly reviewIssueEditable: boolean;
  readonly reviewCount: number;
  /** FEAT-001: a recording session is in progress (loopback/mic). */
  readonly isRecording: boolean;
  /** FEAT-001 (#80): the recording session is paused. */
  readonly isRecordingPaused: boolean;
  /** FEAT-001: score audition (auto-playback of the score) is on. */
  readonly auditionEnabled: boolean;
  /** Active top-level view. */
  readonly view: AppView;
}

/**
 * The services commands act on. The app supplies implementations; during
 * the spike most are stubs that announce via `announce` so every invocation
 * produces honest feedback in the (aria-live) status bar.
 */
export interface CommandContext {
  openAudio(): void;
  /** Start a transcription job. #148: callers may pin option overrides
   *  (e.g. the review bar's voices-texture retry) without mutating the
   *  stored settings first — avoids a stale-options race. */
  transcribe(overrides?: {
    texture?: "auto" | "mono" | "melody" | "voices" | "chords";
  }): void;
  /**
   * Cooperative `job.cancel` (UI-040): requests cancellation of the
   * in-flight transcription; the job still ends in a terminal `cancelled`
   * event, so callers must not assume an instant stop. Optional so older
   * test contexts keep compiling — an absent implementation is a no-op.
   */
  cancelTranscription?(): void;
  togglePlayPause(): void;
  stop(): void;
  jumpBack(): void;
  jumpForward(): void;
  seekToStart(): void;
  seekToEnd(): void;
  toggleLoop(): void;
  /**
   * FEAT-001 (#60): PC再生音源/マイク録音と楽譜自動演奏。
   * Optional so older test contexts keep compiling.
   */
  captureSystemAudio?(): void;
  captureMicrophone?(): void;
  /** 録音中なら停止して取り込む / 録音していなければ何もしない。 */
  stopCapture?(): void;
  /** 録音を中止して破棄する。 */
  cancelCapture?(): void;
  /** 録音を一時停止する(#80)。 */
  pauseCapture?(): void;
  /** 一時停止した録音を再開する(#80)。 */
  resumeCapture?(): void;
  /** 楽譜の自動演奏トグル(スコアクロックに同期して発音)。 */
  toggleScoreAudition?(): void;
  /** 元音源のミュート切替(#72)。楽譜の演奏だけを聴く用途。 */
  toggleSourceMute?(): void;
  setPitchView(view: PitchViewSetting): void;
  openReview(): void;
  reviewNext(): void;
  reviewPrevious(): void;
  /**
   * UI-050 review-workspace actions (GUI_UX_SPEC §12). Optional like
   * `cancelTranscription` so leaner test contexts keep compiling — an
   * absent implementation is a no-op.
   */
  reviewAccept?(): void;
  reviewDismiss?(): void;
  reviewPlaySource?(): void;
  reviewPitchUp?(): void;
  reviewPitchDown?(): void;
  reviewDeleteOrRestore?(): void;
  exitReview?(): void;
  undo(): void;
  redo(): void;
  openExport(): void;
  /** §13 高度編集: open the live score in the MuseScore GUI (async —
   *  the implementation announces success/failure itself). Optional:
   *  absent = no-op. */
  openInMuseScore?(): void;
  /** #100: プロジェクトを保存 — opens the save-file picker and writes
   *  .hornscribe.json through the engine. Optional like the other
   *  late-binding commands; absent = no-op. */
  saveProject?(): void;
  /** #221: 名前を付けて保存 — always picks a destination even when the
   *  project already has a path. Optional; absent = no-op. */
  saveProjectAs?(): void;
  zoomScoreIn(): void;
  zoomScoreOut(): void;
  zoomScoreFit(): void;
  clearSelection(): void;
  /** #114 (spec 10): select the previous/next note (score workspace). */
  selectAdjacentNote?(direction: 1 | -1): void;
  /** #114 (spec 13): semitone-shift / delete / respell the selected
   *  note outside the review workspace (undoable). */
  editSelectedPitch?(delta: number): void;
  toggleSelectedDeleted?(): void;
  toggleSelectedEnharmonic?(): void;
  /** #115 (spec 13): engine rhythm edits on the selected note —
   *  duration ladder (+1 = ×2, -1 = ÷2), onset shift by min-grid steps,
   *  tie/untie to the contiguous next same-pitch note. Async: the
   *  implementation announces success/failure itself. Optional so
   *  fixture/test contexts keep compiling — absent = no-op. */
  noteDurationScale?(power: number): void;
  shiftSelectedOnset?(steps: number): void;
  toggleSelectedTie?(): void;
  /** #130 (spec 14): open the quantization-settings dialog — the
   *  requantize edit itself is applied via the score controller. */
  openRequantizeDialog?(): void;
  /** #131 (spec 13 post-MVP): split/merge the selected note. */
  splitSelectedNote?(): void;
  mergeSelectedNotes?(): void;
  /** #163: convert the selected rest to a note (missed detection). */
  convertSelectedRest?(): void;
  /** #267: whole-score arrangement transpose — canonical engine edit,
   *  one undo entry; ±12 for the octave actions. */
  transposeScore?(semitones: number): void;
  /** #113: Esc on a waveform selection (AUDIO_READY) - clears the range
   *  back to "all" (spec 8: Esc -> 選択解除). Optional: absent = no-op. */
  clearWaveformSelection?(): void;
  openSettings(): void;
  /** Opens the 診断情報 sheet (§19 — separated from the normal UI). */
  openDiagnostics(): void;
  /** F6 region navigation — implemented by focus/zones. */
  focusNextRegion(): void;
  focusPreviousRegion(): void;
  /**
   * Surface command feedback in the status area (role="status" is
   * aria-live, so Narrator users hear the result — UX_VALIDATION §11).
   */
  announce(message: string): void;
}

/**
 * A single invocable command — the unit the registry, command bar, menus,
 * palette and keyboard dispatcher all share (single source of truth).
 */
export interface Command {
  /** Stable dotted id, e.g. "transport.playPause". */
  readonly id: string;
  /**
   * Japanese title — the only UI language (UI_COPY_CONTRACT). This is what
   * buttons, menus, a palette and screen readers all announce.
   */
  readonly title: string;
  /** Optional longer Japanese description for palettes/menus. */
  readonly description?: string;
  readonly section: CommandSection;
  /**
   * Keyboard bindings in "Ctrl+Shift+Z" notation; whitespace separates
   * chords in a multi-step sequence. The first entry is the canonical
   * binding shown in tooltips / aria-keyshortcuts.
   */
  readonly shortcuts?: readonly string[];
  /**
   * #114: opt-in to sharing a chord with another command whose
   * `isEnabled` predicate is mutually exclusive (e.g. ArrowRight =
   * review.next while reviewing, score.selectNext otherwise). Every
   * command on the shared chord must set this flag; the dispatcher
   * activates the first *enabled* candidate.
   */
  readonly shareShortcut?: boolean;
  /**
   * May run against this snapshot. Default: enabled. Disabled commands are
   * non-executable everywhere — toolbar, menu AND shortcut (issue req:
   * "disabled commands remain non-executable via shortcut").
   */
  readonly isEnabled?: (snapshot: CommandSnapshot) => boolean;
  /**
   * Listed on command surfaces (palette/menus/overflow). Default: visible.
   * Hidden commands still run when enabled — e.g. 採譜し直す vs 採譜.
   */
  readonly isVisible?: (snapshot: CommandSnapshot) => boolean;
  /** May fire while a text field / IME host has focus. Default false. */
  readonly allowInTextInput?: boolean;
  /** May fire while a modal dialog/sheet owns focus. Default false. */
  readonly allowInModal?: boolean;
  /** Re-fires on key auto-repeat. Default false (no accidental toggles). */
  readonly allowRepeat?: boolean;
  /** Execute against live services. */
  readonly run: (ctx: CommandContext, snapshot: CommandSnapshot) => void;
}

import { Toolbar, ToolbarButton, Tooltip } from "@fluentui/react-components";
import {
  FolderOpen24Regular,
  Play24Regular,
  CheckmarkCircle24Regular,
  ArrowExportUp24Regular,
  Settings24Regular,
  MoreHorizontal24Regular,
  PanelRight24Regular,
  Wrench24Regular,
  Open24Regular,
  Mic24Regular,
  Speaker2Regular,
  Stop24Regular,
  Pause24Regular,
  Dismiss24Regular,
  ArrowUp24Regular,
  ArrowDown24Regular,
  ArrowLeft24Regular,
  ArrowRight24Regular,
  Link24Regular,
  MusicNote224Regular,
  TableCellsSplit24Regular,
  TableCellsMerge24Regular,
  ArrowSwap24Regular,
  Save24Regular,
  SaveEdit24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import type { CommandSurface } from "../commands/registry";
import { HsMenu, type HsMenuItem } from "./primitives/Menu";
import { PitchSegmented, type PitchView } from "./PitchSegmented";
import {
  hasWorkspaceRegions,
  type ScreenState,
} from "../workspace/screen";
import type { CaptureState } from "../capture/controller";
import type {
  CaptureDeviceList,
  CaptureSource,
} from "../capture/types";
import { formatTimecode } from "../import/format";

/** 録音経過の短い表示(0:00 形式)。 */
function formatElapsed(seconds: number): string {
  return formatTimecode(seconds);
}

/** Tooltip text: Japanese title plus its canonical shortcut, e.g.
 *  「書き出し（Ctrl+E）」 — shortcut hinting is spec'd on §9 controls. */
function withShortcut(title: string, shortcut?: string): string {
  return shortcut ? `${title}（${shortcut}）` : title;
}

/**
 * Command bar (GUI_UX_SPEC §16, DESIGN_SYSTEM §10).
 * Left: project actions. Center: pitch selector. Right: 要確認/書き出し/設定/overflow.
 * Never scrolls; at <1600px secondary labels collapse to icon+tooltip
 * (§21), at <1200px 設定 moves into the overflow menu. The menu always
 * carries the properties show/close toggle so the panel stays reachable.
 *
 * EMPTY state (§3) hides every score/audio command — only 開く, 設定 and
 * the overflow menu render, so the empty surface stays free of score tools.
 *
 * Every action routes through the command surface (§23): enabled state,
 * Japanese label and shortcut all come from the registry, so the button,
 * the menu item and the keyboard binding can never disagree.
 */
export function CommandBar({
  commands,
  pitch,
  screen,
  reviewCount,
  compact,
  propertiesOpen,
  onToggleProperties,
  captureState,
  captureDevices,
  captureSelectedDevice,
  onSelectCaptureDevice,
  onCaptureMenuOpen,
}: {
  commands: CommandSurface;
  pitch: PitchView;
  screen: ScreenState;
  reviewCount: number;
  /** <1200px breakpoint — 設定 lives in the overflow menu instead. */
  compact: boolean;
  propertiesOpen: boolean;
  onToggleProperties(): void;
  /** FEAT-001 (#60): live capture state for the recording affordance. */
  captureState?: CaptureState | null;
  /** #73: 取り込みデバイス一覧(メニュー開時に最新化される)。 */
  captureDevices?: CaptureDeviceList | null;
  /** 選択中のデバイス ID(null = 既定)。 */
  captureSelectedDevice?(source: CaptureSource): string | null;
  onSelectCaptureDevice?(source: CaptureSource, id: string | null): void;
  /** メニューが開いた時にデバイス一覧を取り直す。 */
  onCaptureMenuOpen?(): void;
}) {
  // 採譜 ↔ 採譜し直す — same command slot, label follows score presence
  // (the registry hides retranscribe until a score exists).
  const transcribeId = "score.transcribe";
  const retranscribeId = "score.retranscribe";
  const transcribe = commands.isVisible(retranscribeId)
    ? retranscribeId
    : transcribeId;

  const onPitch = (v: PitchView) =>
    commands.invoke(v === "concert" ? "view.concertPitch" : "view.hornF");

  // EMPTY and the import error states (§3/§20) keep the command bar to
  // shell actions only — no score/audio commands without a live context.
  const loaded = hasWorkspaceRegions(screen);
  const hasScore =
    screen === "scoreReady" || screen === "reviewing" || screen === "exporting";
  const transcribeTooltip = hasScore
    ? ja.commandBar.retranscribeTooltip
    : ja.commandBar.transcribeTooltip;
  const reviewLabel =
    reviewCount > 0
      ? ja.commandBar.reviewWithCount.replace("{count}", String(reviewCount))
      : ja.commandBar.review;

  const overflowItems: HsMenuItem[] = [
    ...(compact
      ? [
          {
            key: "settings",
            label: commands.title("app.settings"),
            icon: <Settings24Regular />,
          } satisfies HsMenuItem,
        ]
      : []),
    {
      key: "properties",
      label: propertiesOpen ? ja.properties.close : ja.properties.show,
      icon: <PanelRight24Regular />,
    },
    // #221: プロジェクトの保存 — 書き出し(export)とは別物として
    // メニューに常駐させる。Ctrl+S/Ctrl+Shift+S と同じコマンド。
    ...(hasScore
      ? [
          {
            key: "save",
            label: commands.title("project.save"),
            icon: <Save24Regular />,
            disabled: !commands.isEnabled("project.save"),
          } satisfies HsMenuItem,
          {
            key: "save-as",
            label: commands.title("project.saveAs"),
            icon: <SaveEdit24Regular />,
            disabled: !commands.isEnabled("project.saveAs"),
          } satisfies HsMenuItem,
        ]
      : []),
    // §13 高度編集: hand the live score to MuseScore (score only — the
    // item hides on import screens like the 書き出し button does).
    ...(hasScore
      ? [
          {
            key: "musescore",
            label: commands.title("export.openInMuseScore"),
            icon: <Open24Regular />,
            disabled: !commands.isEnabled("export.openInMuseScore"),
          } satisfies HsMenuItem,
        ]
      : []),
    // #115 (spec 13): per-note rhythm edits — menu-only discoverability;
    // the keyboard chords do the real work. Disabled without a note
    // selection (the command registry owns the gate).
    ...(hasScore
      ? [
          { key: "rhythm-divider", divider: true } satisfies HsMenuItem,
          {
            key: "note-longer",
            label: commands.title("score.noteLonger"),
            icon: <ArrowUp24Regular />,
            disabled: !commands.isEnabled("score.noteLonger"),
          } satisfies HsMenuItem,
          {
            key: "note-shorter",
            label: commands.title("score.noteShorter"),
            icon: <ArrowDown24Regular />,
            disabled: !commands.isEnabled("score.noteShorter"),
          } satisfies HsMenuItem,
          {
            key: "note-shift-left",
            label: commands.title("score.noteShiftLeft"),
            icon: <ArrowLeft24Regular />,
            disabled: !commands.isEnabled("score.noteShiftLeft"),
          } satisfies HsMenuItem,
          {
            key: "note-shift-right",
            label: commands.title("score.noteShiftRight"),
            icon: <ArrowRight24Regular />,
            disabled: !commands.isEnabled("score.noteShiftRight"),
          } satisfies HsMenuItem,
          {
            key: "note-tie",
            label: commands.title("score.toggleTie"),
            icon: <Link24Regular />,
            disabled: !commands.isEnabled("score.toggleTie"),
          } satisfies HsMenuItem,
          // #131 (spec 13 post-MVP): split/merge — same selection gate.
          {
            key: "note-split",
            label: commands.title("score.splitNote"),
            icon: <TableCellsSplit24Regular />,
            disabled: !commands.isEnabled("score.splitNote"),
          } satisfies HsMenuItem,
          {
            key: "note-merge",
            label: commands.title("score.mergeNotes"),
            icon: <TableCellsMerge24Regular />,
            disabled: !commands.isEnabled("score.mergeNotes"),
          } satisfies HsMenuItem,
          // #163/#167: rest -> note — only enabled on a rest selection.
          {
            key: "rest-to-note",
            label: commands.title("score.restToNote"),
            icon: <ArrowSwap24Regular />,
            disabled: !commands.isEnabled("score.restToNote"),
          } satisfies HsMenuItem,
          // #130 (spec 14): score-wide re-quantize — always enabled with
          // a score (no selection needed); opens the settings dialog.
          {
            key: "requantize",
            label: commands.title("score.requantize"),
            icon: <MusicNote224Regular />,
            disabled: !commands.isEnabled("score.requantize"),
          } satisfies HsMenuItem,
        ]
      : []),
    { key: "overflow-divider", divider: true },
    // §16: diagnostics lives in the overflow, never on the command bar.
    {
      key: "diagnostics",
      label: commands.title("app.diagnostics"),
      icon: <Wrench24Regular />,
    },
  ];

  // FEAT-001: capture menu lives next to 開く — sources of new audio.
  // #73: 各ソースの下にそのソースのデバイス選択を並べる。選択中は ✓。
  const deviceItems = (
    source: CaptureSource,
    devices: readonly { id: string; name: string; isDefault: boolean }[],
  ): HsMenuItem[] => {
    // デバイスが1台も無いソース(ブラウザ dev の loopback 等)は
    // セクション自体を出さない — 既定しか選べない行は誤解を招く。
    if (devices.length === 0) return [];
    const selected = captureSelectedDevice?.(source) ?? null;
    const sectionLabel =
      source === "loopback"
        ? ja.capture.loopbackDeviceLabel
        : ja.capture.microphoneDeviceLabel;
    const items: HsMenuItem[] = [
      { key: source + "-hdr", label: sectionLabel, disabled: true },
      {
        key: source + ":default",
        label:
          selected === null
            ? "\u2713 " + ja.capture.defaultDevice
            : ja.capture.defaultDevice,
      },
    ];
    for (const d of devices) {
      items.push({
        key: source + ":" + d.id,
        label: selected === d.id ? "\u2713 " + d.name : d.name,
      });
    }
    return items;
  };
  const captureMenuItems: HsMenuItem[] = [
    {
      key: "loopback",
      label: commands.title("media.captureSystemAudio"),
      icon: <Speaker2Regular />,
      disabled: !commands.isEnabled("media.captureSystemAudio"),
    },
    {
      key: "microphone",
      label: commands.title("media.captureMicrophone"),
      icon: <Mic24Regular />,
      disabled: !commands.isEnabled("media.captureMicrophone"),
    },
    // デバイスセクションは一覧が取れた時だけ出す(ブラウザ dev では
    // loopback は空、mic のみ)。両方空なら区切り線ごと出さない。
    ...(captureDevices &&
    (captureDevices.loopback.length > 0 ||
      captureDevices.microphone.length > 0)
      ? ([
          { key: "devices-divider", divider: true },
          ...deviceItems("loopback", captureDevices.loopback),
          ...deviceItems("microphone", captureDevices.microphone),
        ] satisfies HsMenuItem[])
      : []),
  ];
  const recording = captureState?.phase === "recording";
  const captureLabel =
    recording && captureState?.source === "loopback"
      ? ja.transport.recordingLoopbackLabel
      : recording
        ? ja.transport.recordingLabel
        : "取り込み";

  return (
    <Toolbar
      className="hs-commandbar"
      aria-label={ja.commandBar.regionLabel}
      data-hs-focus-zone="commandbar"
      tabIndex={-1}
    >
      <Tooltip content={ja.commandBar.openTooltip} relationship="label">
        <ToolbarButton
          icon={<FolderOpen24Regular />}
          disabled={!commands.isEnabled("file.openAudio")}
          aria-keyshortcuts="Control+O"
          onClick={() => commands.invoke("file.openAudio")}
        >
          <span className="hs-commandbar__label">{ja.commandBar.openLabel}</span>
        </ToolbarButton>
      </Tooltip>
      {loaded ? (
        <Tooltip content={transcribeTooltip} relationship="label">
          <ToolbarButton
            icon={<Play24Regular />}
            disabled={!commands.isEnabled(transcribe)}
            appearance="primary"
            onClick={() => commands.invoke(transcribe)}
          >
            <span className="hs-commandbar__label">
              {commands.title(transcribe)}
            </span>
          </ToolbarButton>
        </Tooltip>
      ) : null}

      {loaded ? <span className="hs-commandbar__spacer" /> : null}
      {loaded ? <PitchSegmented value={pitch} onChange={onPitch} /> : null}
      <span className="hs-commandbar__spacer" />

      {/* FEAT-001: 録音ソース — EMPTY/READY どちらでも新しい音源を取り込める。
          録音中は「停止して取り込む」「やめる」の 2 操作に切り替わる。 */}
      {!recording ? (
        <HsMenu
          trigger={
            <ToolbarButton icon={<Mic24Regular />} aria-label={captureLabel}>
              <span className="hs-commandbar__label">{captureLabel}</span>
            </ToolbarButton>
