    expect(p.scoreResult).toBeNull();
  });

  it("extracts transcription.settings provenance (#264)", () => {
    const p = parse({
      schemaVersion: 1,
      projectId: "x",
      sourceAudio: null,
      transcription: {
        revision: "tr-0123456789abcdef",
        backend: "basicPitch",
